def hasValidPath(grid):
    rows, cols = len(grid), len(grid[0])
    # Directions: right=0, left=1, down=2, up=3
    # Street connects: 1: left-right, 2: up-down, 3: left-down, 4: right-down, 5: left-up, 6: right-up
    connects = {
        1: [0, 1], 2: [2, 3], 3: [1, 2], 4: [0, 2], 5: [1, 3], 6: [0, 3]
    }
    dirs = [(0,1,0,1),(0,-1,1,0),(1,0,2,3),(-1,0,3,2)]  # (dr, dc, out_dir, in_dir)
    visited = {(0,0)}
    queue = deque([(0,0)])
    while queue:
        r, c = queue.popleft()
        if r == rows-1 and c == cols-1: return True
        for dr, dc, out_d, in_d in dirs:
