def closestMeetingNode(edges, node1, node2):
    def get_dist(start):
        dist = {}
        d = 0
        while start != -1 and start not in dist:
            dist[start] = d
            d += 1
            start = edges[start]
        return dist

    dist1 = get_dist(node1)
    dist2 = get_dist(node2)
    best_node, best_dist = -1, float('inf')
    for node in dist1:
