def numBusesHard(routes, source, target):
    if source == target: return 0
    stop_to_routes = defaultdict(set)
    for i, route in enumerate(routes):
        for stop in route: stop_to_routes[stop].add(i)
    visited_stops = {source}
    visited_routes = set()
    queue = deque([source])
    buses = 0
    while queue:
        buses += 1
        for _ in range(len(queue)):
            stop = queue.popleft()
            for ri in stop_to_routes[stop]:
                if ri in visited_routes: continue
                visited_routes.add(ri)
                for ns in routes[ri]:
                    if ns == target: return buses
                    if ns not in visited_stops:
                        visited_stops.add(ns)
                        queue.append(ns)
    return -1

from functools import lru_cache

def removeBoxes(boxes):
    @lru_cache(maxsize=None)
    def dp(l, r, k):
        if l > r: return 0
        # Extend k if adjacent boxes match
        while l < r and boxes[l] == boxes[l+1]:
            l += 1; k += 1
        # Remove boxes[l] and k attached boxes
        result = (k+1)**2 + dp(l+1, r, 0)
        # Try merging with a later matching box
        for m in range(l+1, r+1):
            if boxes[m] == boxes[l]:
                result = max(result, dp(l+1, m-1, 0) + dp(m, r, k+1))
        return result
    return dp(0, len(boxes)-1, 0)

