    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb: parent[ra] = rb; count[0] -= 1
    result = []
    for r, c in positions:
        if (r,c) in parent: result.append(count[0]); continue
        parent[(r,c)] = (r,c); count[0] += 1
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
