def minimumCostWithDiscounts(n, highways, discounts):
    graph = defaultdict(list)
    for u, v, w in highways: graph[u].append((v,w)); graph[v].append((u,w))
    INF = float('inf')
    dist = [[INF]*(discounts+1) for _ in range(n)]
    dist[0][0] = 0; heap = [(0,0,0)]
    while heap:
        cost, node, used = heapq.heappop(heap)
        if cost > dist[node][used]: continue
        for nei, w in graph[node]:
            nc = cost+w
            if nc < dist[nei][used]: dist[nei][used]=nc; heapq.heappush(heap,(nc,nei,used))
            if used < discounts:
                nc2 = cost+w//2
                if nc2 < dist[nei][used+1]: dist[nei][used+1]=nc2; heapq.heappush(heap,(nc2,nei,used+1))
    ans = min(dist[n-1])
    return ans if ans < INF else -1

