def findCriticalAndPseudoCriticalEdges(n, edges):
    indexed = sorted(enumerate(edges), key=lambda x: x[1][2])
    def kruskal(skip=-1, force=-1):
        parent = list(range(n))
        def find(x):
            while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
            return x
        weight = cnt = 0
        if force >= 0:
            u,v,w = edges[force]; parent[find(u)]=find(v); weight+=w; cnt+=1
        for orig_i,(u,v,w) in indexed:
            if orig_i==skip: continue
            ru,rv=find(u),find(v)
            if ru!=rv: parent[ru]=rv; weight+=w; cnt+=1
        return weight if cnt==n-1 else float('inf')
    base = kruskal()
    critical=[]; pseudo=[]
    for orig_i,_ in indexed:
        if kruskal(skip=orig_i) > base: critical.append(orig_i)
        elif kruskal(force=orig_i) == base: pseudo.append(orig_i)
    return [critical, pseudo]

