def chromaticNumber(n, edges):
    adj = [0]*n
    for u,v in edges: adj[u]|=1<<v; adj[v]|=1<<u
    is_ind=[False]*(1<<n)
    for mask in range(1<<n):
        ok=True
        for i in range(n):
            if mask>>i&1 and adj[i]&mask: ok=False; break
        is_ind[mask]=ok
    dp=[n+1]*(1<<n); dp[0]=0
    for mask in range(1,1<<n):
        sub=mask
        while sub:
            if is_ind[sub]: dp[mask]=min(dp[mask],dp[mask^sub]+1)
            sub=(sub-1)&mask
    return dp[(1<<n)-1]

def findEulerianPath(n, edges):
    graph = defaultdict(list)
    in_deg=[0]*n; out_deg=[0]*n
    for u,v in edges: graph[u].append(v); out_deg[u]+=1; in_deg[v]+=1
    start=-1
    for i in range(n):
        if out_deg[i]-in_deg[i]==1: start=i; break
    if start==-1:
        for i in range(n):
            if out_deg[i]>0: start=i; break
    if start==-1: return []
    path=[]; stack=[start]
    while stack:
        node=stack[-1]
        if graph[node]: stack.append(graph[node].pop())
        else: path.append(stack.pop())
    path.reverse()
    return path if len(path)==len(edges)+1 else []

