    for i in range(n): dp[1<<i][i]=True
    for mask in range(1,1<<n):
        for v in range(n):
            if not dp[mask][v]: continue
            for u in range(n):
                if not(mask>>u&1) and adj[v][u]: dp[mask|(1<<u)][u]=True
    return any(dp[full_mask][v] for v in range(n))

